// Reads a JSON numeric percentage without accepting booleans or strings.
inline bool readGain(JsonVariant value, int& gain) {
  if (value.is<JsonInteger>()) {
    const JsonInteger number = value.as<JsonInteger>();
    gain = number <= 0 ? 0 : number >= BusRgbCalibration::MAX_GAIN ? BusRgbCalibration::MAX_GAIN : int(number);
    return true;
  }
  if (value.is<JsonUInt>()) {
    const JsonUInt number = value.as<JsonUInt>();
    gain = number >= JsonUInt(BusRgbCalibration::MAX_GAIN) ? BusRgbCalibration::MAX_GAIN : int(number);
    return true;
  }
  if (!value.is<JsonFloat>()) return false;

  const JsonFloat number = value.as<JsonFloat>();
  if (!isfinite(number)) return false;
  gain = number <= 0 ? 0 : number >= BusRgbCalibration::MAX_GAIN ? BusRgbCalibration::MAX_GAIN : int(number);
  return true;
}

// Reads an integral GPIO selector; only -1 represents an intentionally unset output.
template<typename GpioValidator>
inline bool readOutputGpio(JsonVariant value, int& dataGpio, GpioValidator gpioIsUsable) {
  if (value.is<JsonInteger>()) {
    const JsonInteger number = value.as<JsonInteger>();
    if (number == -1) {
      dataGpio = -1;
      return true;
    }
    if (number < 0 || number >= BusRgbCalibration::UNSET_GPIO) return false;
    const int candidate = int(number);
    if (!gpioIsUsable(candidate)) return false;
    dataGpio = candidate;
    return true;
  }
  if (value.is<JsonUInt>()) {
    const JsonUInt number = value.as<JsonUInt>();
    if (number >= JsonUInt(BusRgbCalibration::UNSET_GPIO)) return false;
    const int candidate = int(number);
    if (!gpioIsUsable(candidate)) return false;
    dataGpio = candidate;
    return true;
  }
  return false;
}

// Builds one complete state tuple from a current snapshot, retaining values for malformed fields.
template<typename GpioValidator>
inline ReadResult read(JsonObject root, uint32_t currentState, GpioValidator gpioIsUsable) {
  JsonObject top = root[NAME];
  bool complete = !top.isNull();
  bool isEnabled = BusRgbCalibration::enabled(currentState);
  int dataGpio = BusRgbCalibration::gpio(currentState);
  int redGain = BusRgbCalibration::red(currentState);
  int greenGain = BusRgbCalibration::green(currentState);
  int blueGain = BusRgbCalibration::blue(currentState);

  if (top.isNull() || !top[ENABLED].is<bool>()) complete = false;
  else isEnabled = top[ENABLED].as<bool>();
  if (top.isNull() || !readOutputGpio(top[OUTPUT_GPIO], dataGpio, gpioIsUsable)) complete = false;
  if (top.isNull() || !readGain(top[RED_GAIN], redGain)) complete = false;
  if (top.isNull() || !readGain(top[GREEN_GAIN], greenGain)) complete = false;
  if (top.isNull() || !readGain(top[BLUE_GAIN], blueGain)) complete = false;

  return {BusRgbCalibration::pack(dataGpio, isEnabled, redGain, greenGain, blueGain), complete};
}

// Serializes all settings from one state snapshot, including saved gains while disabled.
